import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;

import java.io.IOException;
import java.io.Serial;

public class GetRolesAPI extends WebserverAPI {
    @Serial
    private static final long serialVersionUID = 3387051963302327281L;

    public GetRolesAPI(Main main) {
        super(main, RECIPE_ID.USER_ROLES.toString());
    }

    @Override
    public String getPath() {
        return "/recipe/roles";
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) throws IOException, ServletException {
        // API is app specific
        try {
            AppIdentifier appIdentifier = getAppIdentifier(req);
            Storage storage = enforcePublicTenantAndGetPublicTenantStorage(req);

            String[] roles = UserRoles.getRoles(appIdentifier, storage);
            JsonArray arr = new JsonArray();

            for (String s : roles) {
                arr.add(new JsonPrimitive(s));
            }

            JsonObject response = new JsonObject();
            response.add("roles", arr);
            response.addProperty("status", "OK");
            super.sendJsonResponse(200, response, resp);

        } catch (StorageQueryException | TenantOrAppNotFoundException | BadPermissionException e) {
            throw new ServletException(e);
        }
    }

}
